import os
import torch

# =============================================================================
# PATHS & DIRECTORIES
# =============================================================================
INPUT_DIR = "./input"
METADATA_DIR = "./metadata"
WORKING_DIR = "./working/idea_6"
SUBMISSION_DIR = "./submission"

# Metadata Files (Generated by metadata script)
TRAIN_META_FILE = os.path.join(METADATA_DIR, "train.csv")
VAL_META_FILE = os.path.join(METADATA_DIR, "val.csv")
TEST_META_FILE = os.path.join(METADATA_DIR, "test.csv")

# Raw Data Files (Read-only input)
TRAIN_RAW_FILE = os.path.join(INPUT_DIR, "train.csv")
TEST_RAW_FILE = os.path.join(INPUT_DIR, "test.csv")
SAMPLE_SUBMISSION_FILE = os.path.join(INPUT_DIR, "sample_submission.csv")

# Output Artifacts
MODEL_PATH = os.path.join(WORKING_DIR, "wide_deep_model.pth")
SUBMISSION_FILE = os.path.join(SUBMISSION_DIR, "submission.csv")

# Caching Paths (for deterministic data processing)
TOKENIZER_PATH = os.path.join(WORKING_DIR, "tokenizer.json")
MLB_PATH = os.path.join(WORKING_DIR, "mlb.joblib")
TRAIN_FEATURES_PATH = os.path.join(WORKING_DIR, "train_features.npy")
TRAIN_LABELS_PATH = os.path.join(WORKING_DIR, "train_labels.npy")
VAL_FEATURES_PATH = os.path.join(WORKING_DIR, "val_features.npy")
VAL_LABELS_PATH = os.path.join(WORKING_DIR, "val_labels.npy")
TEST_FEATURES_PATH = os.path.join(WORKING_DIR, "test_features.npy")
TEST_IDS_PATH = os.path.join(WORKING_DIR, "test_ids.npy")

# =============================================================================
# DATA PROCESSING HYPERPARAMETERS
# =============================================================================
SEED = 42
VOCAB_SIZE = 50000  # Vocabulary size for tokenization
MAX_LEN = 400  # Maximum sequence length (Title + Body)
TOP_K_TAGS = 5000  # Number of most frequent tags to predict
NUM_WORKERS = 4  # Number of subprocesses for data loading

# =============================================================================
# MODEL ARCHITECTURE HYPERPARAMETERS
# =============================================================================
# Wide-and-Deep TextCNN settings
EMBED_DIM = 128  # Dimension for embeddings
NUM_FILTERS = 128  # Number of filters per kernel size in CNN
KERNEL_SIZES = [3, 4, 5]  # N-gram window sizes for CNN
DROPOUT = 0.5  # Dropout rate

# =============================================================================
# TRAINING HYPERPARAMETERS
# =============================================================================
BATCH_SIZE = 512  # Batch size (A100 can handle large batches)
LEARNING_RATE = 1e-3  # Initial learning rate
EPOCHS = 10  # Maximum number of training epochs
PATIENCE = 3  # Early stopping patience
DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

# =============================================================================
# INITIALIZATION
# =============================================================================
# Ensure necessary writable directories exist
os.makedirs(WORKING_DIR, exist_ok=True)
os.makedirs(SUBMISSION_DIR, exist_ok=True)
